import net.neoforged.neoforge.client.event.ClientTickEvent;
@EventBusSubscriber(modid="revoextraction",value=Dist.CLIENT)
public class MachineGalleryQa {
 static boolean started,done;static volatile boolean ready;static int index,frames;static final BlockPos ORIGIN=new BlockPos(0,180,0);static final List<String> names=new ArrayList<>();static final List<String> captured=new ArrayList<>();
 static {for(var tier:DrillTier.values())names.add(tier.prefix());for(var kind:MachineKind.values())names.add(kind.id);for(var tier:FurnaceTier.values())names.add(tier.id+"_multiblock_furnace");names.addAll(List.of("rain_barrel","clay_crucible","unfired_crucible","composter","silkworm_cultivator","power_converter","advanced_power_converter","elite_power_converter","vacuum_1","vacuum_2","vacuum_3","electric_drill","trading_colony","chest_drive","crafting_terminal","salt_crystal_growth","nether_wart_growth","chorus_growth","poppy_growth","ghast_colony","shulker_colony","wither_skeleton_colony"));}
 static Path dir(){return Path.of("../../screenshots/machines").toAbsolutePath().normalize();}
 static void prepare(){ready=false;var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{var player=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());var l=player.serverLevel();if(!l.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).toString().contains("Revo Machine Gallery QA"))throw new IllegalStateException("Gallery save required");player.closeContainer();player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);l.setDayTime(1000);l.setWeatherParameters(100000,0,false,false);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false,l.getServer());
 for(int x=-7;x<=7;x++)for(int y=-1;y<=12;y++)for(int z=-7;z<=9;z++)l.setBlockAndUpdate(ORIGIN.offset(x,y,z),y==-1?Blocks.SMOOTH_STONE.defaultBlockState():Blocks.AIR.defaultBlockState());
 String name=names.get(index);
 if(index<3){var tier=DrillTier.values()[index];l.setBlockAndUpdate(ORIGIN,tier.block(DrillLayout.Part.CONTROLLER).defaultBlockState());var m=(DrillMachine)l.getBlockEntity(ORIGIN);for(int x=-1;x<=1;x++)for(int y=0;y<3;y++)for(int z=-1;z<=1;z++){var part=tier.part(x,y,z);var state=tier.block(part).defaultBlockState();if(part==DrillLayout.Part.INPUT)state=state.setValue(DrillInput.FACING,Direction.EAST);if(part==DrillLayout.Part.HATCH)state=state.setValue(DrillHatch.FACING,Direction.WEST);l.setBlockAndUpdate(m.at(x,y,z),state);}if(!m.checkStructure())throw new IllegalStateException("Drill failed formation");
 }else if(index<9||index>=34){var kind=index>=38?MachineKind.STEEL_HARVESTER:index==35||index==36?MachineKind.IRON_GREENHOUSE:index>=34?MachineKind.GREENHOUSE:MachineKind.values()[index-3];l.setBlockAndUpdate(ORIGIN,kind.controller().defaultBlockState());var m=(FarmMachine)l.getBlockEntity(ORIGIN);for(int x=-kind.radius();x<=kind.radius();x++)for(int y=0;y<kind.height;y++)for(int z=-kind.radius();z<=kind.radius();z++){var part=kind.part(x,y,z);var state=kind.block(part).defaultBlockState();if(part==MachineKind.Part.HATCH)state=state.setValue(FarmHatch.FACING,Direction.EAST);if(part==MachineKind.Part.FILTER)state=state.setValue(FarmFilter.FACING,Direction.NORTH);if(part==MachineKind.Part.POWER)state=state.setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,Direction.SOUTH);l.setBlockAndUpdate(m.at(x,y,z),state);}if(!m.checkStructure())throw new IllegalStateException("Farm failed formation");if(!kind.isHarvester())m.inputs.setStackInSlot(0,new ItemStack(kind.isTree()?Items.OAK_SAPLING:Items.WHEAT_SEEDS));m.water.fill(new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,8000),net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);m.receiveEu(1600,false);if(index>=34){int[] programs={19,17,18,31,28,29,30};int selected=programs[index-34];if(kind.isHarvester()){l.setBlockAndUpdate(m.at(0,1,-1),l.getBlockState(m.at(0,1,-1)).setValue(FarmFilter.SPECIES,selected==28?8:selected==29?9:10));m.inputs.setStackInSlot(0,new ItemStack(Items.NETHERITE_INGOT));}else{m.inputs.setStackInSlot(0,MachineKind.starter(selected));if(selected==17||selected==18)l.setBlockAndUpdate(m.at(0,-1,0),(selected==17?Blocks.SOUL_SAND:Blocks.END_STONE).defaultBlockState());}}for(int i=0;i<kind.ticks/2+5;i++)FarmMachine.tick(l,ORIGIN,m.getBlockState(),m);
 }else if(index<19){var tier=FurnaceTier.values()[index-9];l.setBlockAndUpdate(ORIGIN,Furnaces.CONTROLLERS.get(tier).get().defaultBlockState());var m=(FurnaceController)l.getBlockEntity(ORIGIN);m.orientation.facingDirection=Direction.NORTH;for(var entry:m.getActiveShape().simpleMembers.entrySet())l.setBlockAndUpdate(ShapeMatcher.toWorldPos(ORIGIN,Direction.NORTH,entry.getKey()),entry.getValue().getPreviewState());int[][] ports={{-1,0,0},{1,0,0},{0,0,2}};l.setBlockAndUpdate(ShapeMatcher.toWorldPos(ORIGIN,Direction.NORTH,new BlockPos(-1,0,0)),Furnaces.ITEM_HATCHES.get(tier.factoryTier*2).get().defaultBlockState());l.setBlockAndUpdate(ShapeMatcher.toWorldPos(ORIGIN,Direction.NORTH,new BlockPos(1,0,0)),Furnaces.ITEM_HATCHES.get(tier.factoryTier*2+1).get().defaultBlockState());l.setBlockAndUpdate(ShapeMatcher.toWorldPos(ORIGIN,Direction.NORTH,new BlockPos(0,0,2)),Furnaces.FUEL_HATCHES.get(tier.factoryTier*3).get().defaultBlockState());m.tick();if(!m.isShapeValid())throw new IllegalStateException("Furnace failed formation "+tier);
 }else{String mod=name.equals("composter")||name.equals("silkworm_cultivator")||name.equals("trading_colony")?"revocultivation":name.equals("chest_drive")||name.equals("crafting_terminal")?"revostorage":name.equals("electric_drill")?"revoextraction":"revoindustry";var block=net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath(mod,name));if(block==Blocks.AIR)throw new IllegalStateException("Missing machine "+name);l.setBlockAndUpdate(ORIGIN,block.defaultBlockState());}
 l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(-8,179,-8,8,194,10)).forEach(net.minecraft.world.entity.Entity::discard);player.connection.teleport(index==6?9:6,index==6?186:183,index==6?-11:-7,0,0);player.getAbilities().flying=true;player.onUpdateAbilities();ready=true;
 }catch(Exception ex){try{Files.createDirectories(dir());Files.writeString(dir().resolve("FAILED.txt"),names.get(index)+": "+ex);}catch(Exception ignored){}throw new RuntimeException(ex);}});}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(done||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(mc.screen instanceof net.minecraft.client.gui.screens.PauseScreen)mc.setScreen(null);if(!started){started=true;mc.options.pauseOnLostFocus=false;mc.options.hideGui=true;mc.options.fov().set(55);prepare();return;}if(!ready)return;mc.player.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,new Vec3(.5,index==6?183:181,1));if(++frames<65)return;try{Files.createDirectories(dir());try(var im=Screenshot.takeScreenshot(mc.getMainRenderTarget())){im.writeToFile(dir().resolve(String.format("%02d-%s.png",index+1,names.get(index))));}captured.add(names.get(index));if(++index>=names.size()){Files.writeString(dir().resolve("INDEX.md"),"# Custom machine screenshots\n\nCaptured in the isolated gallery save after implementation. All multiblocks passed formation before capture.\n\n"+String.join("\n",captured.stream().map(n->"- "+n).toList()));done=true;mc.options.hideGui=false;mc.stop();}else{frames=0;prepare();}}catch(Exception ex){throw new RuntimeException(ex);}}
}
